import sys

def count_pairs(n, m):
    count = 0
    for x in range(1, n + 1):
        for y in range(1, m + 1):
            if (x + y) % 5 == 0:
                count += 1
    return count

def main():
    import sys
    input = sys.stdin.read().strip()
    n, m = map(int, input.split())
    result = count_pairs(n, m)
    print(result)

if __name__ == "__main__":
    main()
